int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int W, H;
    cin >> W >> H;

    vector<pair<long long,int>> edges; // (cost, type): type 0 = horizontal (p), type 1 = vertical (q)

    for (int i = 0; i < W; i++) {
        long long p;
        cin >> p;
        edges.push_back({p, 0});
    }
    for (int j = 0; j < H; j++) {
        long long q;
        cin >> q;
        edges.push_back({q, 1});
    }

    sort(edges.begin(), edges.end());

    long long col_groups = W + 1;
    long long row_groups = H + 1;
    long long total_cost = 0;

    for (auto& [cost, type] : edges) {
        if (type == 0) {
            // horizontal edge: merge two column groups
            // need row_groups edges
            total_cost += cost * row_groups;
            col_groups--;
        } else {
            // vertical edge: merge two row groups
            // need col_groups edges
            total_cost += cost * col_groups;
            row_groups--;
        }
    }

    cout << total_cost << endl;

    return 0;
}

