    for (int j = 0; j < H; j++) cin >> q[j];

    vector<pair<long long, int>> edges;
    edges.reserve(W + H);

    // type 0: horizontal separator cost p_i
    // type 1: vertical separator cost q_j
    for (int i = 0; i < W; i++) edges.push_back({p[i], 0});
    for (int j = 0; j < H; j++) edges.push_back({q[j], 1});

    sort(edges.begin(), edges.end());

    long long groupsX = W + 1; // number of current vertical components
    long long groupsY = H + 1; // number of current horizontal components
    long long ans = 0;

    for (auto [cost, type] : edges) {
        if (type == 0) {
            // connect two adjacent x-columns across all current y-components
            ans += cost * groupsY;
            groupsX--;
        } else {
            // connect two adjacent y-rows across all current x-components
            ans += cost * groupsX;
            groupsY--;
        }
    }

    cout << ans << '\n';
    return 0;
}

