#include <stdio.h>
#include <stdlib.h>

typedef struct {
    long long cost;
    int type; // 0 = p (horizontal, connects columns), 1 = q (vertical, connects rows)
} Edge;

int cmp(const void *a, const void *b) {
    Edge *ea = (Edge*)a, *eb = (Edge*)b;
    if (ea->cost != eb->cost) return (ea->cost > eb->cost) - (ea->cost < eb->cost);
    return ea->type - eb->type;
}

int main() {
    int W, H;
    scanf("%d %d", &W, &H);

    Edge *edges = malloc((W + H) * sizeof(Edge));
    for (int i = 0; i < W; i++) {
        scanf("%lld", &edges[i].cost);
        edges[i].type = 0;
    }
    for (int j = 0; j < H; j++) {
        scanf("%lld", &edges[W+j].cost);
        edges[W+j].type = 1;
    }

    qsort(edges, W + H, sizeof(Edge), cmp);

    long long total = 0;
    int rcount = 0, ccount = 0;

    for (int i = 0; i < W + H; i++) {
        if (edges[i].type == 0) {
            // p edge: connects columns, used (H+1-rcount) times
            total += edges[i].cost * (H + 1 - rcount);
            ccount++;
        } else {
            // q edge: connects rows, used (W+1-ccount) times
            total += edges[i].cost * (W + 1 - ccount);
            rcount++;
        }
    }

    printf("%lld\n", total);
    free(edges);
    return 0;
}

