typedef long long ll;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int W, H;
    if (scanf("%d %d", &W, &H) != 2) return 0;

    ll *p = (ll *)malloc(sizeof(ll) * W);
    ll *q = (ll *)malloc(sizeof(ll) * H);
    if (!p || !q) return 0;

    for (int i = 0; i < W; i++) scanf("%lld", &p[i]);
    for (int i = 0; i < H; i++) scanf("%lld", &q[i]);

    qsort(p, W, sizeof(ll), cmp_ll);
    qsort(q, H, sizeof(ll), cmp_ll);

    int i = 0, j = 0;
    ll vertical_groups = H + 1;   // number of current row-components
    ll horizontal_groups = W + 1; // number of current column-components
    ll ans = 0;

    while (i < W && j < H) {
        if (p[i] < q[j]) {
            ans += p[i] * vertical_groups;
            horizontal_groups--;
            i++;
        } else {
            ans += q[j] * horizontal_groups;
            vertical_groups--;
            j++;
        }
    }

    while (i < W) {
        ans += p[i] * vertical_groups;
        i++;
    }
    while (j < H) {
        ans += q[j] * horizontal_groups;
        j++;
    }

    printf("%lld\n", ans);

    free(p);
    free(q);
    return 0;
}

