public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        int W = Integer.parseInt(parts[0]);
        int H = Integer.parseInt(parts[1]);

        int[] p = new int[W];
        int[] q = new int[H];

        for (int i = 0; i < W; i++) {
            p[i] = Integer.parseInt(br.readLine());
        }
        for (int i = 0; i < H; i++) {
            q[i] = Integer.parseInt(br.readLine());
        }

        Arrays.sort(p);
        Arrays.sort(q);

        long total = 0;
        int rowIdx = 0, colIdx = 0;
        // Initially we have (W+1)*(H+1) components
        // Each horizontal road connects across H+1 nodes in a column sense,
        // Each vertical road connects across W+1 nodes in a row sense.
        // We'll use the classic approach:
        int rows = W + 1;
        int cols = H + 1;

        while (rowIdx < W || colIdx < H) {
            if (colIdx >= H || (rowIdx < W && p[rowIdx] < q[colIdx])) {
                total += (long) p[rowIdx] * cols;
                rows--;
                rowIdx++;
            } else {
                total += (long) q[colIdx] * rows;
                cols--;
                colIdx++;
            }
        }

        System.out.println(total);
    }
}

