import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Edge implements Comparable<Edge> {
        long cost;
        int type; // 0: horizontal-gap edge (between x columns), 1: vertical-gap edge (between y rows)

        Edge(long cost, int type) {
            this.cost = cost;
            this.type = type;
        }

        public int compareTo(Edge other) {
            return Long.compare(this.cost, other.cost);
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int W = fs.nextInt();
        int H = fs.nextInt();

        Edge[] edges = new Edge[W + H];
        for (int i = 0; i < W; i++) {
            edges[i] = new Edge(fs.nextLong(), 0);
        }
        for (int j = 0; j < H; j++) {
            edges[W + j] = new Edge(fs.nextLong(), 1);
        }

        Arrays.sort(edges);

        long colGroups = W + 1L; // current number of connected x-components
        long rowGroups = H + 1L; // current number of connected y-components
        long ans = 0;

        for (Edge e : edges) {
            if (e.type == 0) {
                // connect two adjacent x-groups, needed across all current row groups
                ans += e.cost * rowGroups;
                colGroups--;
            } else {
                // connect two adjacent y-groups, needed across all current column groups
                ans += e.cost * colGroups;
                rowGroups--;
            }
        }

        System.out.println(ans);
    }
}

import sys

def solve():
    input = sys.stdin.readline
    W, H = map(int, input().split())
    p = [int(input()) for _ in range(W)]
    q = [int(input()) for _ in range(H)]

    # sort costs with their type: 0 for horizontal (p), 1 for vertical (q)
    edges = []
    for i, cost in enumerate(p):
        edges.append((cost, 0, i))
    for j, cost in enumerate(q):
        edges.append((cost, 1, j))
    edges.sort()

    # Union-Find
    parent = list(range((W+1)*(H+1)))
    rank = [0] * ((W+1)*(H+1))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    total_cost = 0
    # Initially, we have (W+1)*(H+1) components
    h_components = W + 1   # number of horizontal segments initially
    v_components = H + 1   # number of vertical segments initially

    for cost, typ, idx in edges:
        if typ == 0:  # horizontal edges (p)
            # connect all vertical strips for this row
            for j in range(H):
                u = idx * (H+1) + j
                v = idx * (H+1) + (j+1)
                if union(u, v):
                    total_cost += cost
        else:  # vertical edges (q)
            for i in range(W):
                u = i * (H+1) + idx
                v = (i+1) * (H+1) + idx
                if union(u, v):
                    total_cost += cost

    print(total_cost)

